-- Cadastro inicial de quantidades e sabores (pesquisa de mercado, 23/10/2026). Já aplicado no banco.
-- Creatina: preços reais (200 g: R$ 59,90 natural / R$ 69,90 com sabor). Coenzima Q10 60 cápsulas: R$ 54,90.
insert into public.sabores (id,name,display_order) select id,name,display_order from jsonb_to_recordset($c$[{"id": "laranja", "name": "Laranja", "display_order": 0}, {"id": "limao", "name": "Limão", "display_order": 1}, {"id": "morango", "name": "Morango", "display_order": 2}, {"id": "uva", "name": "Uva", "display_order": 3}, {"id": "frutas-vermelhas", "name": "Frutas vermelhas", "display_order": 4}, {"id": "maracuja", "name": "Maracujá", "display_order": 5}, {"id": "abacaxi", "name": "Abacaxi", "display_order": 6}, {"id": "tangerina", "name": "Tangerina", "display_order": 7}, {"id": "melancia", "name": "Melancia", "display_order": 8}, {"id": "cereja", "name": "Cereja", "display_order": 9}, {"id": "pessego", "name": "Pêssego", "display_order": 10}, {"id": "baunilha", "name": "Baunilha", "display_order": 11}, {"id": "chocolate", "name": "Chocolate", "display_order": 12}, {"id": "coco", "name": "Coco", "display_order": 13}, {"id": "menta", "name": "Menta", "display_order": 14}, {"id": "tutti-frutti", "name": "Tutti-frutti", "display_order": 15}]$c$::jsonb) as x(id text,name text,display_order int) on conflict (id) do nothing;
