update public.produtos p set price = coalesce((select min((s->>'price')::numeric) from jsonb_array_elements(p.options->'sizes') s where coalesce((s->>'price')::numeric,0) > 0), 0) where jsonb_array_length(coalesce(p.options->'sizes','[]'::jsonb)) > 0;
update public.produtos set description = btrim(regexp_replace(description, '\s*Contém [^.]*\.\s*$', '')) where description ~ 'Contém [^.]*\.\s*$';
update public.produtos set description = replace(replace(replace(description, 'Creatina Monohidratada 200g.', 'Creatina Monohidratada.'), 'Fórmula pura e sem sabor.', 'Disponível pura (sem sabor) ou com sabor.'), 'Whey Protein Isolado 500g.', 'Whey Protein Isolado.') where id in (15,16);
update public.produtos set description = replace(description, 'L-Glutamina em pó 300g.', 'L-Glutamina em pó.') where id = 25;
